// Input contract: { candidatePaths: string[], excludeFolderId?: number|null }
// Normalizes each candidate path to a trailing-slash-free absolute path so
// prefix comparisons downstream are exact (PROJ-74).
const path = require('path');

function normalize(p) {
  let n = path.normalize(String(p || ''));
  if (n.length > 1 && n.endsWith('/')) n = n.slice(0, -1);
  return n;
}

const input = $input.first().json;
const candidatePaths = Array.isArray(input.candidatePaths) ? input.candidatePaths.map(normalize) : [];
let excludeFolderId = input.excludeFolderId != null ? parseInt(input.excludeFolderId, 10) : null;
if (excludeFolderId !== null && isNaN(excludeFolderId)) excludeFolderId = null;

return [{ json: { candidatePaths, excludeFolderId } }];

// Ancestor/Descendant conflict check (PROJ-74), string-prefix comparison of
// normalized absolute paths, evaluated only against active (enabled=true) folders
// at depth >= 1 below /mnt/nas — the mount point itself is never treated as an
// ancestor of anything (it's a shared prefix of every registered folder, not a
// meaningful conflict source; it's excluded from selection entirely upstream).
const MOUNT = '/mnt/nas';
const { candidatePaths } = $('Code: Normalize Input').first().json;
const activeFolders = ($input.first().json.folders || []).filter(f => f && f.path && f.path !== MOUNT);

function conflictFor(candidate) {
  if (candidate === MOUNT) return { conflictType: null, message: null };
  for (const folder of activeFolders) {
    const active = folder.path;
    if (candidate === active) {
      return { conflictType: 'exact', message: 'Dieser Ordner ist bereits als DMS-Ordner erfasst.' };
    }
    if (candidate.startsWith(active + '/')) {
      // candidate lies below an already-watched folder
      return { conflictType: 'ancestor', message: 'Dieser Ordner liegt unterhalb eines bereits erfassten Ordners.' };
    }
    if (active.startsWith(candidate + '/')) {
      // candidate would contain an already-watched folder
      return { conflictType: 'descendant', message: 'Dieser Ordner enthält einen bereits erfassten Ordner.' };
    }
  }
  return { conflictType: null, message: null };
}

// A Code node emitting zero items breaks the caller's downstream chain (n8n
// skips nodes that receive zero input items), so always emit at least one
// item — a sentinel when there was nothing to check.
if (candidatePaths.length === 0) {
  return [{ json: { _empty: true } }];
}

// Refinement 2026-08-04: only an EXACT path match blocks Create/Update.
// Ancestor/Descendant overlap is now an accepted trade-off (real NAS layouts
// need a broad collector folder alongside specifically-typed subfolders) —
// conflictType is still classified/returned for informational badges in the
// Browse endpoint, but hasConflict (what POST/PUT gate on) no longer fires
// for 'ancestor'/'descendant'.
return candidatePaths.map(p => {
  const c = conflictFor(p);
  return { json: { path: p, conflictType: c.conflictType, message: c.message, hasConflict: c.conflictType === 'exact' } };
});
